import json
import math
import statistics

dates = ["2024-01-02", "2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09"]
closes = {
    "AAA": [100.0, 101.5, 100.8, 102.3, 103.0, 102.1],
    "BBB": [50.0, 49.2, 49.9, 50.6, 50.1, 51.0],
}
tickers = sorted(closes)
rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
w = 2
vol = {
    t: [None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))]
    for t, r in rets.items()
}


def summary(t):
    r = rets[t]
    ar = 252 * statistics.mean(r)
    av = math.sqrt(252) * statistics.stdev(r)
    return {"ticker": t, "ann_return": ar, "ann_vol": av, "sharpe": ar / av, "last_vol": vol[t][-1]}


def drawdown(t):
    wealth, peak, peak_d = 1.0, 1.0, dates[0]
    best = (0.0, dates[0], dates[0])
    for d, r in zip(dates[1:], rets[t], strict=True):
        wealth *= math.exp(r)
        if wealth > peak:
            peak, peak_d = wealth, d
        depth = wealth / peak - 1
        if depth < best[0]:
            best = (depth, peak_d, d)
    return {"ticker": t, "depth": best[0], "peak_date": best[1], "trough_date": best[2]}


out = {
    "prices": {"dates": dates, "tickers": tickers, "closes": closes},
    "returns": {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets},
    "vol": vol,
    "summary": [summary(t) for t in tickers],
    "drawdown": [drawdown(t) for t in tickers],
}
print(json.dumps(out, indent=2))

